# IMPERIA COLD WAR — country-specific independent party concept profiles.
"""Party route identity and signature concepts. Data only; no output is written."""

import content as c


def _signature(title, description, modifiers, gdp_cost, kind, research=None):
    item = dict(title=title, description=description, modifiers=modifiers,
                gdp_cost=gdp_cost, kind=kind)
    if research is not None:
        item['research'] = research
    return item


def _profile(root_title, root_description, anti_communist, economic_identity,
             source_note, signature_a, signature_b):
    return dict(root_title=root_title, root_description=root_description,
                anti_communist=anti_communist, economic_identity=economic_identity,
                source_note=source_note, signatures=[signature_a, signature_b])


